var Q27 = [
  {n:1,q:'El artículo 35.1 de la Ley Orgánica 4/2015, de 30 de marzo, de Protección de la Seguridad Ciudadana (desde ahora LOPSC) tipifica como infracción muy grave:',o:{a:'Las reuniones o manifestaciones no comunicadas o prohibidas en infraestructuras o instalaciones en las que se prestan servicios básicos para la comunidad pero no en sus inmediaciones.',b:'Las reuniones o manifestaciones no comunicadas o prohibidas en infraestructuras o instalaciones en las que se prestan servicios básicos para la comunidad o en sus inmediaciones.',c:'La intrusión en infraestructuras o instalaciones críticas como instalaciones, redes, sistemas y equipos físicos y de tecnología de la información.',d:'El sobrevuelo sobre infraestructuras o instalaciones en las que se prestan servicios básicos para la comunidad o en sus inmediaciones aún cuando no se genere un riesgo para la vida o la integridad física de las personas.'},correct:'b',why:{b:'El art. 35.1 LOPSC tipifica como infracción muy grave "las reuniones o manifestaciones no comunicadas o prohibidas en infraestructuras o instalaciones en las que se prestan servicios básicos para la comunidad o en sus inmediaciones, así como la intrusión en los recintos de éstas, incluido su sobrevuelo, cuando, en cualquiera de estos supuestos, se haya generado un riesgo para la vida o la integridad física de las personas". Se incluyen tanto el interior como las inmediaciones; la intrusión y sobrevuelo solo se sancionan si generan riesgo para la vida o integridad física.'}},
  {n:2,q:'¿Quiénes serán los responsables en el caso de reuniones o manifestaciones no comunicadas o prohibidas en infraestructuras o instalaciones en las que se prestan servicios básicos para la comunidad o en sus inmediaciones?',o:{a:'Los organizadores.',b:'Los promotores.',c:'Los organizadores y los promotores.',d:'Los organizadores, los promotores, los portavoces y los asistentes.'},correct:'b',why:{b:'El artículo 35.1 de la LOPSC especifica que "en el caso de las reuniones y manifestaciones serán responsables los organizadores o promotores". El art. 30.3 LOPSC considera organizadores o promotores a quienes hayan suscrito la comunicación o quienes de hecho las presidan, dirijan o ejerzan actos semejantes.'}},
  {n:3,q:'Si no se hubiera generado un riesgo para la vida o la integridad física de las personas como consecuencia de la intrusión en un recinto infraestructuras o instalaciones en las que se prestan servicios básicos para la comunidad, pero sí se hubiera producido una interferencia grave en su funcionamiento:',o:{a:'No se producirá ninguna infracción.',b:'Se producirá una infracción leve.',c:'Se producirá una infracción grave.',d:'Se producirá un delito penal.'},correct:'b',why:{b:'Según el marcador del libro, la solución es b). La explicación del texto señala que cuando no se produce riesgo para la vida pero sí interferencia grave se aplica el art. 36.9 LOPSC (infracción grave), y cuando ni siquiera existe interferencia grave pero la concentración no fue comunicada, se aplica la infracción leve del art. 37.1 LOPSC.'}},
  {n:4,q:'El artículo 35.2 de la LOPSC en relación con armas reglamentarias, explosivos, cartuchería o artículos pirotécnicos tipifica como infracción muy grave:',o:{a:'La realización de distintas acciones detalladas en el propio precepto.',b:'La omisión, insuficiencia, o falta de eficacia de las medidas de seguridad o precauciones que resulten obligatorias, siempre que en tales actuaciones se causen perjuicios muy graves.',c:'Ambas respuestas son correctas.',d:'Ambas respuestas son falsas.'},correct:'c',why:{c:'El art. 35.2 LOPSC contiene dos infracciones distintas: por un lado, la realización de las acciones típicas (fabricación, reparación, almacenamiento, etc.) incumpliendo la normativa o sin documentación; por otro, la omisión, insuficiencia o falta de eficacia de las medidas de seguridad, siempre que se causen perjuicios muy graves.'}},
  {n:5,q:'El artículo 35.4 de la LOPSC tipifica como infracción muy grave la proyección de haces de luz, mediante cualquier tipo de dispositivo ¿sobre qué tipo de sujetos?',o:{a:'Sobre pilotos de aeronaves.',b:'Sobre conductores de medios de transporte.',c:'Sobre pilotos o conductores de medios de transporte.',d:'Sobre pilotos, conductores de medios de transporte o vehículos particulares.'},correct:'c',why:{c:'El art. 35.4 LOPSC tipifica como infracción muy grave "la proyección de haces de luz, mediante cualquier tipo de dispositivo, sobre los pilotos o conductores de medios de transporte que puedan deslumbrarles o distraer su atención y provocar accidentes". Quedan fuera los vehículos particulares.'}},
  {n:6,q:'El artículo 36.1 de la LOPSC no tipifica como infracción grave la perturbación de la seguridad ciudadana cuando no sea constitutiva de infracción penal:',o:{a:'En actos públicos.',b:'En espectáculos deportivos o culturales.',c:'En solemnidades y oficios religiosos.',d:'En la audiencia de un tribunal o juzgado, en los actos públicos propios de cualquier autoridad o corporación.'},correct:'d',why:{d:'El art. 36.1 LOPSC tipifica la perturbación de la seguridad ciudadana en actos públicos, espectáculos deportivos o culturales, solemnidades y oficios religiosos u otras reuniones numerosas, cuando no sea constitutiva de infracción penal. La audiencia de un tribunal o juzgado corresponde al art. 558 CP (delito), no a esta infracción administrativa.'}},
  {n:7,q:'El artículo 36.2 de la LOPSC tipifica como infracción grave la perturbación grave de la seguridad ciudadana que se produzca con ocasión de reuniones o manifestaciones frente a las sedes parlamentarias:',o:{a:'Si la asamblea en cuestión se encontrara reunida.',b:'Solamente si la asamblea en cuestión no se encontrara reunida.',c:'Cuando constituya infracción penal.',d:'Resultando indiferente si la asamblea está reunida o no lo está.'},correct:'d',why:{d:'El art. 36.2 LOPSC tipifica la infracción grave frente a sedes parlamentarias "aunque no estuvieran reunidas, cuando no constituya infracción penal". Resulta indiferente que la asamblea esté o no reunida. Si estuviese reunida y se alterase el funcionamiento de la Cámara, los hechos podrían constituir delito contra las instituciones del Estado (art. 494 CP).'}},
  {n:8,q:'El artículo 36.2 de la LOPSC tipifica como infracción grave los comportamientos que supongan una alteración grave de la seguridad ciudadana y que se produzcan frente a las sede:',o:{a:'Del Congreso de los Diputados.',b:'Del Congreso de los Diputados o del Senado.',c:'Del Congreso de los Diputados, del Senado o de las asambleas legislativas de las Comunidades Autónomas.',d:'Del Congreso de los Diputados, del Senado, de las asambleas legislativas de las Comunidades Autónomas o de los Ayuntamientos y Diputaciones Provinciales.'},correct:'c',why:{c:'El art. 36.2 tipifica como infracción grave la perturbación grave frente a las sedes del Congreso de los Diputados, el Senado y las asambleas legislativas de las comunidades autónomas, aunque no estuvieran reunidas, cuando no constituya infracción penal. No se incluyen Ayuntamientos ni Diputaciones Provinciales.'}},
  {n:9,q:'De acuerdo con el artículo 36.3 de la LOPSC causar desórdenes en las vías, espacios o establecimientos públicos, u obstaculizar la vía pública con mobiliario urbano, vehículos, contenedores, neumáticos u otros objetos, se considera infracción grave cuando en ambos casos se ocasione:',o:{a:'Daños en el mobiliario urbano.',b:'Una alteración leve de la seguridad ciudadana.',c:'Una alteración grave de la seguridad ciudadana.',d:'Actuando en grupo.'},correct:'c',why:{c:'El art. 36.3 LOPSC tipifica como infracción grave "causar desórdenes en las vías, espacios o establecimientos públicos, u obstaculizar la vía pública con mobiliario urbano, vehículos, contenedores, neumáticos u otros objetos, cuando en ambos casos se ocasione una alteración grave de la seguridad ciudadana". No es necesario actuar en grupo ni causar daños.'}},
  {n:10,q:'El artículo 36.4 de la LOPSC sanciona con respecto a los desahucios que deban ser ejecutados por la autoridad:',o:{a:'Los actos de protesta que pretendan impedir su ejecución.',b:'Los actos de obstrucción que pretendan impedir su ejecución siempre que se produzcan al margen de los procedimientos legalmente establecidos y no sean constitutivos de delito.',c:'Los actos de protesta u obstrucción que pretendan impedir su ejecución siempre que se produzcan al margen de los procedimientos legalmente establecidos y no sean constitutivos de delito.',d:'Los actos de concentración en el lugar que deban ser ejecutados o en sus inmediaciones que pretendan impedir el desahucio.'},correct:'b',why:{b:'El art. 36.4 LOPSC tipifica como infracción grave "los actos de obstrucción que pretendan impedir a cualquier autoridad, empleado público o corporación oficial el ejercicio legítimo de sus funciones... siempre que se produzcan al margen de los procedimientos legalmente establecidos y no sean constitutivos de delito". No sanciona los meros actos de protesta ni los escraches sin obstaculización efectiva.'}},
  {n:11,q:'¿Qué requiere la infracción grave del artículo 36.5 de la LOPSC que sanciona las acciones y omisiones que impidan u obstaculicen el funcionamiento de los servicios de emergencia?',o:{a:'Que se provoque o incremente un riesgo para la vida o integridad de las personas.',b:'Que se provoque o incremente un daño en los bienes.',c:'Que se agraven las consecuencias del suceso que motive la actuación de los servicios de emergencia.',d:'Todas las respuestas son correctas.'},correct:'d',why:{d:'El art. 36.5 LOPSC tipifica como infracción grave las acciones u omisiones que impidan u obstaculicen los servicios de emergencia, "provocando o incrementando un riesgo para la vida o integridad de las personas o de daños en los bienes, o agravando las consecuencias del suceso que motive la actuación de aquéllos". Las tres condiciones son alternativas, por lo que todas las opciones son correctas.'}},
  {n:12,q:'¿Qué tipo de identificaciones por parte de los miembros de las Fuerzas y Cuerpos de Seguridad del Estado están totalmente prohibidas?',o:{a:'Las que se realicen sobre extranjeros indocumentados.',b:'Las que tengan lugar en domicilios privados.',c:'Las que se lleven a cabo sobre menores indocumentados.',d:'Las que se lleven a cabo por el perfil étnico o las características físicas de la persona en cuestión.'},correct:'d',why:{d:'Está totalmente prohibido que se requiera la identificación por el perfil étnico o las características físicas de la persona. Este criterio fue consolidado por el Comité de Derechos Humanos de Naciones Unidas en el caso Williams Lecraft contra España, que obligó al Estado español a cambiar su doctrina y reconocer que el criterio racial no puede ser base para la sospecha.'}},
  {n:13,q:'Si como consecuencia de actos de perturbación se hubiera impedido el desarrollo de la reunión o manifestación lícita, es decir, ésta no hubiera podido celebrarse o hubiera tenido que suspenderse:',o:{a:'Se produciría una infracción administrativa y no una infracción penal.',b:'Se produciría una infracción penal y no una infracción administrativa.',c:'No se producirá ni infracción penal ni infracción administrativa.',d:'Ninguna respuesta es correcta.'},correct:'b',why:{b:'El art. 36.7 LOPSC tipifica como infracción grave la perturbación del desarrollo de una reunión o manifestación lícita, cuando no constituya infracción penal. Sin embargo, si como consecuencia de los actos de perturbación se impide el desarrollo de la reunión (no puede celebrarse o se suspende), nunca podrá aplicarse la infracción administrativa y los hechos serán constitutivos del delito del art. 514.4 CP.'}},
  {n:14,q:'¿En qué supuesto la intrusión o sobrevuelo de infraestructuras que prestan servicios básicos no se sanciona ni penal ni administrativamente?',o:{a:'Si no supone un riesgo para la vida o integridad física de las personas.',b:'Si se provoca una interferencia grave en el funcionamiento de dichas instalaciones.',c:'Si se provoca una interferencia leve en el funcionamiento de dichas instalaciones.',d:'Si se provoca cualquier tipo de interferencia en el funcionamiento de dichas instalaciones.'},correct:'c',why:{c:'El art. 36.9 LOPSC tipifica como infracción grave la intrusión con "interferencia grave (y no leve) en el funcionamiento de dichas instalaciones". La infracción muy grave del art. 35.1 requiere riesgo para la vida. Si la intrusión solo provoca interferencia leve, el hecho es atípico y no se puede sancionar ni penal ni administrativamente.'}},
  {n:15,q:'En relación con las armas de fuego prohibidas siempre se considera delito penal:',o:{a:'Su tenencia.',b:'Su porte.',c:'Su exhibición.',d:'Su uso.'},correct:'a',why:{a:'El art. 36.10 LOPSC tipifica como infracción grave "portar, exhibir o usar armas prohibidas... siempre que dichas conductas no constituyan infracción penal". La tenencia ilícita de armas de fuego queda fuera de esta infracción administrativa, pues siempre es constitutiva de delito (arts. 563 y ss. CP).'}},
  {n:16,q:'En relación con las armas prohibidas no se considerará infracción administrativa:',o:{a:'Su uso, en cualquier caso, aún cuando se tuviera licencia.',b:'Su exhibición en los lugares habilitados para su uso.',c:'Su uso temerario o intimidatorio en cualquier caso.',d:'Su uso en los lugares habilitados para ello.'},correct:'c',why:{c:'El art. 36.10 LOPSC establece que el uso temerario o intimidatorio será constitutivo de infracción administrativa "siempre que no constituya infracción penal". Por tanto, cuando el uso temerario o intimidatorio constituya infracción penal, no se considerará infracción administrativa. La opción c) es incorrecta al afirmar que lo será "en cualquier caso", sin contemplar la excepción penal.'}},
  {n:17,q:'En relación con el ejercicio de la prostitución en ciertos lugares el artículo 36.11 de la LOPSC sanciona:',o:{a:'A las personas que soliciten servicios sexuales retribuidos.',b:'A las personas que acepten servicios sexuales retribuidos.',c:'A las personas que ofrezcan servicios sexuales retribuidos.',d:'Todas las respuestas son correctas.'},correct:'d',why:{d:'El art. 36.11 LOPSC tipifica como infracción grave "la solicitud o aceptación por el demandante de servicios sexuales retribuidos" en ciertos lugares. Además, en su segundo párrafo establece que los agentes requerirán a quienes ofrezcan estos servicios que se abstengan, informándoles de que la inobservancia podría constituir una infracción del párrafo 6 del mismo artículo.'}},
  {n:18,q:'¿Cuál de las siguientes opciones de respuesta no es correcta para que tenga lugar la infracción administrativa prevista en el artículo 36.10 de la LOPSC?',o:{a:'Los servicios sexuales no deberán ser retribuidos.',b:'Las conductas sexuales, por el lugar en que se realicen, deberán generar un riesgo para la seguridad vial.',c:'Los servicios sexuales deberán tener lugar en las proximidades de centros educativos.',d:'Los servicios sexuales deberán tener lugar en las proximidades de parques infantiles.'},correct:'a',why:{a:'El art. 36.11 LOPSC exige que los servicios sexuales sean retribuidos, lo que deja fuera de sanción los favores sexuales gratuitos. Además, la infracción requiere que se realice en zonas de tránsito público en proximidades de lugares para menores o que puedan generar riesgo para la seguridad vial.'}},
  {n:19,q:'La obstrucción de las inspecciones o controles reglamentarios, establecidos conforme a lo dispuesto en el artículo 36.13 de la LOPSC, en fábricas, locales, establecimientos, embarcaciones y aeronaves tendrá la consideración de infracción [grave] siempre que dicha obstrucción sea:',o:{a:'Efectiva.',b:'Deliberada.',c:'Activa.',d:'Planificada.'},correct:'b',why:{b:'El art. 36.13 LOPSC tipifica como infracción grave "la negativa de acceso o la obstrucción deliberada de las inspecciones o controles reglamentarios, establecidos conforme a lo dispuesto en esta Ley, en fábricas, locales, establecimientos, embarcaciones y aeronaves". El requisito es que la obstrucción sea deliberada.'}},
  {n:20,q:'El uso público e indebido de uniformes, insignias o condecoraciones oficiales tendrá la consideración de infracción grave:',o:{a:'Si genera engaño acerca de la condición de quien los use.',b:'Si se produce en fiestas de carnaval.',c:'Si se trata de originales y no réplicas de los mismos.',d:'Solo si forman parte del equipamiento de los cuerpos policiales.'},correct:'a',why:{a:'El art. 36.14 LOPSC tipifica el uso público e indebido de uniformes, insignias o condecoraciones oficiales, o réplicas de los mismos, así como otros elementos del equipamiento de los cuerpos policiales o servicios de emergencia que puedan generar engaño acerca de la condición de quien los use. Queda excluido en fiestas de carnaval o similares, pues en tales circunstancias el uso no tiene dicha finalidad.'}},
  {n:21,q:'El deber de colaboración con las Fuerzas y Cuerpos de Seguridad en la averiguación de delitos o en la prevención de acciones que puedan poner en riesgo la seguridad ciudadana se impone a:',o:{a:'Las autoridades y funcionarios públicos.',b:'Los particulares.',c:'Las empresas de seguridad privada.',d:'Todas las respuestas son correctas.'},correct:'d',why:{d:'El art. 7 LOPSC consagra el deber de colaboración no solo de las autoridades y funcionarios públicos, sino también de los particulares, detectives, empresas y empleados de seguridad privada, así como el personal que desarrolle funciones de policía administrativa. Lo que sanciona el art. 36.15 es el incumplimiento de ese deber.'}},
  {n:22,q:'Según lo dispuesto en la LOPSC se sanciona administrativamente:',o:{a:'El consumo de drogas en cualquier lugar.',b:'El consumo de drogas en ciertos lugares.',c:'El consumo de drogas en cualquier lugar y en cualquier cantidad.',d:'El abandono de los instrumentos empleados para el consumo de drogas en cualquier lugar.'},correct:'b',why:{b:'El art. 36.16 LOPSC tipifica como infracción grave "el consumo o la tenencia ilícitos de drogas tóxicas, estupefacientes o sustancias psicotrópicas, aunque no estuvieran destinadas al tráfico, en lugares, vías, establecimientos públicos o transportes colectivos". Solo en ciertos lugares públicos, no en cualquier lugar.'}},
  {n:23,q:'El artículo 36.18 de la LOPSC tipifica como infracción grave la ejecución de actos de plantación y cultivo ilícitos de drogas tóxicas, estupefacientes o sustancias psicotrópicas:',o:{a:'En domicilios particulares.',b:'En lugares visibles al público.',c:'En lugares que se puedan apreciar a través de los sentidos corporales.',d:'En lugares en los que pueda desprender olor.'},correct:'b',why:{b:'El art. 36.17 LOPSC tipifica como infracción grave la plantación y cultivo ilícitos de drogas "en lugares visibles al público, cuando no sean constitutivos de infracción penal". Por el principio de tipicidad, no son sancionables los supuestos en que la plantación no esté visible al público aunque pueda apreciarse por el olfato, ni cuando lo visible sean solo elementos del cultivo (chimeneas de ventilación).'}},
  {n:24,q:'La infracción administrativa relacionada con el consumo ilegal o el tráfico de drogas tóxicas, estupefacientes o sustancias psicotrópicas en locales o establecimientos públicos no sanciona:',o:{a:'La tolerancia del consumo por parte de los propietarios del local.',b:'La falta de diligencia en orden a impedir el consumo por parte del propietario del local.',c:'La venta o distribución en el establecimiento público por parte del propietario del local.',d:'Toda las anteriores conductas se sancionan administrativamente.'},correct:'c',why:{c:'El art. 36.19 LOPSC tipifica como infracción grave la tolerancia del consumo ilegal o el tráfico de drogas en locales o establecimientos públicos, o la falta de diligencia en impedirlos. Se trata de una infracción estrictamente omisiva. La venta o distribución activa en establecimiento es la modalidad agravada del art. 369 CP (delito), no esta infracción administrativa.'}},
  {n:25,q:'La carencia de los registros previstos en la LOPSC para realizar una actividad requiere para que tenga la consideración de infracción [grave] que:',o:{a:'Las actividades tengan trascendencia para la seguridad ciudadana.',b:'Las actividades requieran licencia administrativa.',c:'Las actividades se puedan calificar como peligrosas.',d:'Las actividades tengan trascendencia medioambiental.'},correct:'a',why:{a:'El art. 36.20 LOPSC tipifica como infracción grave "la carencia de los registros previstos en esta Ley para las actividades con trascendencia para la seguridad ciudadana o la omisión de comunicaciones obligatorias". El requisito es que las actividades tengan trascendencia para la seguridad ciudadana (hospedaje, compraventa de objetos usados, cerrajería de seguridad, etc.).'}},
  {n:26,q:'El artículo 36.22 de la LOPSC especifica que el incumplimiento de las restricciones a la navegación para que tenga la consideración de infracción [grave] deberá afectar a:',o:{a:'Las embarcaciones de alta velocidad y aeronaves ligeras.',b:'Las embarcaciones neumáticas utilizadas en el contrabando.',c:'Las embarcaciones utilizadas para el tráfico ilegal de inmigrantes.',d:'Las aeronaves que no requieran licencia de vuelo.'},correct:'a',why:{a:'El art. 36.22 LOPSC tipifica como infracción grave "el incumplimiento de las restricciones a la navegación reglamentariamente impuestas a las embarcaciones de alta velocidad y aeronaves ligeras", entre las que se podrían incluir los denominados "drones".'}},
  {n:27,q:'El uso de imágenes o datos de las autoridades o miembros de las Fuerzas y Cuerpos de Seguridad ¿puede estar sujeto a autorización administrativa?',o:{a:'Sí, sin que dicha autorización administrativa se pueda considerar censura previa.',b:'Sí, sin que en ningún supuesto su difusión se pueda considerar ilícita.',c:'Sí, si afecta al derecho fundamental a la información.',d:'No, pues es contrario a la interdicción de la censura previa regulada en el artículo 20.2 de la Constitución.'},correct:'d',why:{d:'La STC 172/2020, de 19 de noviembre de 2020 declaró la inconstitucionalidad del inciso "no autorizado" del art. 36.23 LOPSC. La sujeción a autorización administrativa previa para el uso de imágenes o datos de las autoridades o miembros de las Fuerzas y Cuerpos de Seguridad es contraria a la interdicción de la censura previa regulada en el artículo 20.2 de la Constitución Española.'}},
  {n:28,q:'¿En qué supuesto sería lícito que el funcionario policial que se vea grabado en la vía pública exija a quien le graba que le entregue el dispositivo con el que graba para comprobar su contenido?',o:{a:'En el supuesto en el que quien graba no sea un profesional de los medios de comunicación.',b:'En el supuesto en que considere que se puede poner en peligro su seguridad personal o familiar.',c:'En cualquier supuesto siempre que el contenido no sea eliminado del dispositivo.',d:'En ningún supuesto.'},correct:'d',why:{d:'El art. 36.23 LOPSC no tipifica como infracción administrativa la captación de la imagen de los funcionarios policiales. La grabación en el ejercicio de sus funciones no es sancionable. En consecuencia, no es lícito, en ningún supuesto, que el funcionario exija a quien le graba que le entregue el dispositivo para comprobar su contenido, y mucho menos para borrarlo.'}},
  {n:29,q:'¿Qué tipo de comportamiento podría considerarse incluido en la infracción grave prevista en el artículo 36.23 de la LOPSC?',o:{a:'La publicación de imágenes del funcionario policial junto con su nombre y apellidos.',b:'La publicación de imágenes de instalaciones relevantes para la seguridad nacional en la que se vea el número y disposición de los funcionarios destinados a su custodia.',c:'La publicación de imágenes en las que figure el domicilio y número de teléfono del funcionario policial.',d:'Todas las respuestas son correctas.'},correct:'d',why:{d:'Los comportamientos incluidos en esta infracción pueden ser: la publicación de imágenes de funcionarios policiales junto con nombre y apellidos, con su domicilio particular o número de teléfono particular, o imágenes de instalaciones relevantes para la seguridad nacional que muestren el número y disposición de los funcionarios destinados a su custodia, o datos de una investigación en curso que pusieran en peligro el buen fin de la misma.'}},
  {n:30,q:'¿Quién deberá probar que el uso de las imágenes o datos captados pone en peligro la seguridad personal o familiar del agente policial?',o:{a:'El propio ciudadano que graba las imágenes.',b:'La administración sancionante, el funcionario policial o la autoridad que denuncie los hechos.',c:'El propio agente policial gozando sus manifestaciones de presunción de veracidad.',d:'Ninguna respuesta es correcta.'},correct:'b',why:{b:'Quien debe demostrar y probar que el uso de las imágenes o datos captados pone en peligro la seguridad personal o familiar del agente o de las instalaciones protegidas, o en riesgo el éxito de una operación, es la administración sancionante y, por ende, el funcionario policial o la autoridad que denuncia los hechos, sin que sea lícito hacer uso de la presunción de veracidad del art. 52 LOPSC.'}},
  {n:31,q:'El artículo 4.2 de la LOPSC dispone que las disposiciones de la Ley que afecten, entre otras, a la libertad de expresión e información deberán interpretarse y aplicarse:',o:{a:'De manera restrictiva cuando puedan causar una situación de peligro para la seguridad de un agente policial.',b:'Sin que afecten a la presunción de veracidad del agente policial.',c:'Del modo más favorable a la plena efectividad de los derechos fundamentales y libertades públicas.',d:'Todas las respuestas son correctas.'},correct:'c',why:{c:'El art. 4.2 LOPSC establece expresamente que "las disposiciones de los capítulos III y V deberán interpretarse y aplicarse del modo más favorable a la plena efectividad de los derechos fundamentales y libertades públicas, singularmente de los derechos de reunión y manifestación, las libertades de expresión e información, la libertad sindical y el derecho de huelga".'}},
  {n:32,q:'Para que tenga lugar la sanción administrativa prevista en el artículo 36.23 de la LOPSC, los datos e imágenes es necesario que pongan en peligro:',o:{a:'La seguridad personal o familiar de los agentes policiales.',b:'La seguridad personal o familiar de las autoridades.',c:'La seguridad personal o familiar de los agentes policiales y de las autoridades.',d:'Ninguna respuesta es correcta.'},correct:'a',why:{a:'De acuerdo con el art. 36.23 LOPSC, aunque los datos e imágenes cuyo uso no autorizado es sancionado se refieren tanto a las autoridades como a los miembros de las fuerzas y cuerpos de seguridad, la necesidad de la puesta en peligro de la seguridad personal o familiar solo se predica de los agentes, no de las autoridades.'}},
  {n:33,q:'¿Podrían los agentes policiales proceder a la identificación de la persona por el simple hecho de haber grabado las imágenes?',o:{a:'Sí, aún cuando no existan indicios de que se hubiera cometido la infracción.',b:'Sí, pudiendo ser trasladada a las dependencias policiales la persona que hubiese grabado las imágenes.',c:'No, pues si la toma de imágenes no constituye "per se" una infracción administrativa, no se puede proceder a la identificación policial.',d:'No, excepto que el agente policial aprecie indicios de que las imágenes puedan ser borradas.'},correct:'c',why:{c:'La Instrucción 13/2018 de la Secretaría de Estado de Seguridad aclara que "no constituye infracción la mera toma de imágenes" si no pone en riesgo a los agentes. El art. 16.1 LOPSC solo permite la identificación policial cuando existan indicios de participación en una infracción. Si tomar imágenes no es infracción, la identificación por la hipotética comisión futura no está justificada.'}},
  {n:34,q:'La infracción leve regulada en el artículo 37.1 de la LOPSC en relación a la celebración de reuniones en lugares de tránsito público o de manifestaciones podrá ser cometida:',o:{a:'Por quienes simplemente participen en las reuniones o manifestaciones no comunicadas a la autoridad.',b:'Por quienes tengan objetivamente la consideración de promotores u organizadores si han incurrido en dolo o culpa.',c:'Por quienes tengan objetivamente la consideración de promotores u organizadores, en cualquier caso.',d:'Por quienes actúen como portavoces de la reunión o manifestación.'},correct:'b',why:{b:'La infracción del art. 37.1 LOPSC solo puede ser cometida por promotores y organizadores, no por simples participantes. Además, no es suficiente con tener objetivamente esta condición o que se deduzca razonablemente de hechos externos: es necesario que hayan incurrido en dolo o culpa, conforme al principio general de responsabilidad administrativa (art. 28.1 LRJSP).'}},
  {n:35,q:'PLACEHOLDER',o:{a:'', b:'', c:'', d:''},correct:'a',why:{a:'PENDIENTE'}},
  {n:36,q:'PLACEHOLDER',o:{a:'', b:'', c:'', d:''},correct:'a',why:{a:'PENDIENTE'}},
  {n:37,q:'PLACEHOLDER',o:{a:'', b:'', c:'', d:''},correct:'a',why:{a:'PENDIENTE'}},
  {n:38,q:'PLACEHOLDER',o:{a:'', b:'', c:'', d:''},correct:'a',why:{a:'PENDIENTE'}},
  {n:39,q:'PLACEHOLDER',o:{a:'', b:'', c:'', d:''},correct:'a',why:{a:'PENDIENTE'}},
  {n:40,q:'La proyección de haces de luz, mediante cualquier tipo de dispositivo para que tenga la consideración de infracción leve se deberá realizar sobre:',o:{a:'Miembros de las Fuerzas y Cuerpos de Seguridad.',b:'Miembros de las Fuerzas y Cuerpos de Seguridad o autoridades.',c:'Pilotos.',d:'Conductores de medios de transporte.'},correct:'a',why:{a:'El art. 37.6 LOPSC tipifica como infracción leve "la proyección de haces de luz, mediante cualquier tipo de dispositivo, sobre miembros de las Fuerzas y Cuerpos de Seguridad para impedir o dificultar el ejercicio de sus funciones". A diferencia, el art. 35.4 tipifica como infracción muy grave hacerlo sobre pilotos o conductores de medios de transporte que puedan deslumbrarles.'}},
  {n:41,q:'La ocupación de cualquier inmueble, vivienda o edificio ajenos tendrá la consideración de infracción leve:',o:{a:'Siempre que no se permanezca en ellos.',b:'Siempre que se realice en ausencia de violencia.',c:'Si no se realiza contra la voluntad de su propietario o titular del derecho real afectado.',d:'Si no constituye infracción penal.'},correct:'d',why:{d:'El art. 37.7 LOPSC tipifica como infracción leve "la ocupación de cualquier inmueble, vivienda o edificio ajenos, o la permanencia en ellos, en ambos casos contra la voluntad de su propietario, arrendatario o titular de otro derecho sobre el mismo, cuando no sean constitutivas de infracción penal". Quedan excluidos el allanamiento de morada (art. 202.1 CP) y la usurpación (art. 245.2 CP).'}},
  {n:42,q:'La ocupación de la vía pública, de acuerdo con el artículo 37.7 de la LOPSC tendrá la consideración de infracción leve siempre que se realice contra lo dispuesto:',o:{a:'En la Ley.',b:'En la Ley o las normas reglamentarias.',c:'En la Ley, las normas reglamentarias o la decisión adoptada en aplicación de la Ley por la autoridad competente.',d:'Ninguna respuesta es correcta.'},correct:'d',why:{d:'El art. 37.7 LOPSC tipifica la ocupación de la vía pública "con infracción de lo dispuesto por la Ley o contra la decisión adoptada en aplicación de aquella por la autoridad competente". Las SSTC 172/2020 y 13/2021 precisaron que el precepto va referido a normas con rango legal, no a normas reglamentarias. Ninguna de las opciones a, b o c refleja exactamente esta formulación legal.'}},
  {n:43,q:'En relación con las armas y explosivos el artículo 37.8 de la LOPSC no tipifica como infracción leve:',o:{a:'La omisión o insuficiencia de medidas relacionadas con su documentación.',b:'La falta de denuncia en la pérdida de su documentación.',c:'La falta de denuncia en la sustracción de su documentación.',d:'La carencia de la documentación requerida para el uso de las mismas.'},correct:'d',why:{d:'El art. 37.8 LOPSC tipifica como infracción leve "la omisión o la insuficiencia de medidas para garantizar la conservación de la documentación de armas y explosivos, así como la falta de denuncia de la pérdida o sustracción de la misma". La carencia de la documentación requerida para el uso no está tipificada en este precepto.'}},
  {n:44,q:'En relación con la documentación personal legalmente exigida el artículo 37.10 de la LOPSC tipifica como infracción leve la omisión negligente de la denuncia:',o:{a:'De su hurto.',b:'De su hurto y extravío.',c:'De sus sustracción y extravío.',d:'De su hurto y sustracción.'},correct:'c',why:{c:'El art. 37.10 LOPSC tipifica como infracción leve "la omisión negligente de la denuncia de su sustracción o extravío". Se sustituyó el término "hurto" por "sustracción" para comprender también los supuestos de robo con fuerza y violencia, que quedarían excluidos del deber de denuncia si solo se mencionara el hurto.'}},
  {n:45,q:'De acuerdo con el artículo 37.11 de la LOPSC si una persona pierde en un período de seis meses dos veces el DNI:',o:{a:'Podrá ser sancionada por la comisión de una infracción leve.',b:'Podrá ser sancionada por la comisión de una infracción leve cada vez que, con posterioridad, vuelva a perder el documento hasta un año después de la última pérdida.',c:'No podrá ser sancionada aún cuando vuelva a perder el documento hasta un año después de la última pérdida.',d:'Podrá ser sancionada por la comisión de una infracción grave si vuelve a perder el documento hasta un año después de la última pérdida.'},correct:'b',why:{b:'El art. 37.11 LOPSC considera negligencia la "tercera y posteriores pérdidas o extravíos en el plazo de un año". Si una persona pierde dos veces el DNI en seis meses, podrá ser sancionada cada vez que, con posterioridad, vuelva a perder el documento hasta un año después de la última pérdida. Transcurrido un año completo sin pérdida, el contador se reinicia.'}},
  {n:46,q:'¿Cuál de las siguientes opciones de respuesta en relación con los daños o deslucimiento de bienes de uso o servicio público o privado en la vía pública regulado en el artículo 37.13 de la LOPSC no es cierta?',o:{a:'La sanción penal o administrativa tendrá lugar si los daños son cometidos por imprudencia.',b:'La sanción penal o administrativa de los daños tendrá lugar si los daños son cometidos dolosamente.',c:'Solo constituye sanción administrativa el deslucimiento de bienes de uso o servicio público o privado pero no los daños sobre dichos bienes.',d:'El citado precepto de la LOPSC solo puede sancionar el deslucimiento de dichos bienes pero no los daños.'},correct:'a',why:{a:'Los daños causados dolosamente son castigados en el Código Penal (cualquiera que sea su cuantía). Sin embargo, los daños por imprudencia no tienen sanción penal ni administrativa. El art. 37.13 LOPSC únicamente puede usarse para sancionar los actos de deslucimiento (pintadas, grafitis), no los daños materiales, que siempre son delito doloso.'}},
  {n:47,q:'El escalamiento de edificios o monumentos sin autorización tendrá la consideración de infracción administrativa leve:',o:{a:'Solamente cuando exista un riesgo cierto de que se ocasionen daños a las personas.',b:'Solamente cuando exista un riesgo cierto de que se ocasionen daños a los bienes.',c:'Cuando exista un riesgo cierto de que se ocasionen daños a las personas o a los bienes.',d:'Cuando exista un riesgo cierto de que se ocasionen daños a las personas o a los bienes que tengan trascendencia para la seguridad ciudadana.'},correct:'c',why:{c:'El art. 37.14 LOPSC tipifica como infracción leve "el escalamiento de edificios o monumentos sin autorización cuando exista un riesgo cierto de que se ocasionen daños a las personas o a los bienes". No se exige que los bienes tengan trascendencia para la seguridad ciudadana.'}},
  {n:48,q:'El artículo 37.15 de la LOPSC dispone específicamente que la remoción de vallas, encintados u otros elementos fijos o móviles colocados por las Fuerzas y Cuerpos de Seguridad podrá dar lugar a infracción administrativa leve cuando se utilicen:',o:{a:'Para delimitar perímetros de seguridad.',b:'Para regular el tráfico y la seguridad vial.',c:'Para delimitar el recorrido de una manifestación.',d:'Para delimitar el recorrido de pruebas deportivas.'},correct:'a',why:{a:'El art. 37.15 LOPSC tipifica como infracción leve "la remoción de vallas, encintados u otros elementos fijos o móviles colocados por las Fuerzas y Cuerpos de Seguridad para delimitar perímetros de seguridad, aun con carácter preventivo, cuando no constituya infracción grave". Sanciona quitar o cambiar de lugar estos medios de seguridad.'}},
  {n:49,q:'Uno de los supuestos regulados en el artículo 37.16 de la LOPSC en relación con animales y que puede dar lugar a la comisión de una infracción leve es:',o:{a:'Dejar sueltos los animales domésticos en condiciones en que pueda peligrar su vida.',b:'Dejar en condiciones que puedan causar daños los animales domésticos.',c:'Abandonar animales feroces o dañinos en condiciones en que pueda peligrar su vida.',d:'Abandonar animales domésticos en condiciones en que pueda peligrar su vida.'},correct:'d',why:{d:'El art. 37.16 LOPSC tipifica como infracción leve "dejar sueltos o en condiciones de causar daños animales feroces o dañinos, así como abandonar animales domésticos en condiciones en que pueda peligrar su vida". Son dos acciones distintas: dejar sueltos a los feroces (que puedan causar daño), y abandonar a los domésticos (que peligre su vida).'}},
  {n:50,q:'¿Qué condición requiere el consumo de bebidas alcohólicas en lugares, vías, establecimientos o transportes públicos para que tenga lugar la infracción leve regulada en el artículo 37.17 de la LOPSC?',o:{a:'Que se realice en presencia de menores de edad.',b:'Que se realice fuera del horario autorizado para ello.',c:'Que perturbe gravemente la tranquilidad ciudadana.',d:'Que perturbe levemente la seguridad ciudadana.'},correct:'c',why:{c:'El art. 37.17 LOPSC tipifica como infracción leve "el consumo de bebidas alcohólicas en lugares, vías, establecimientos o transportes públicos cuando perturbe gravemente la tranquilidad ciudadana". La infracción exige perturbación grave de la tranquilidad ciudadana, lo que requeriría acreditar que el ruido generado supera los límites reglamentariamente establecidos.'}},
  {n:51,q:'En los casos de infracciones continuadas ¿cuándo se empieza a computar el plazo para la prescripción de las infracciones?',o:{a:'Desde que se cometió la última de las infracciones.',b:'Desde que se pone fin al resultado ilícito.',c:'Desde que se cometió la primera de las infracciones.',d:'Desde que da comienzo el resultado ilícito.'},correct:'a',why:{a:'El art. 38.2 LOPSC dispone que en las infracciones continuadas los plazos se computarán "desde el día en que se realizó la última infracción". En las infracciones de efectos permanentes, el plazo se computa desde que se eliminó la situación ilícita (opción b), no desde la última infracción.'}},
  {n:52,q:'El plazo de prescripción de las infracciones se interrumpe:',o:{a:'Desde el día siguiente a aquel en que sea ejecutable la resolución por la que se impone la sanción.',b:'Cuando haya transcurrido el plazo para recurrir la sanción.',c:'Por cualquier actuación administrativa de la que tenga conocimiento formal el interesado dirigida a la sanción de la infracción.',d:'Ninguna respuesta es correcta.'},correct:'c',why:{c:'El art. 38.3 LOPSC dispone que "la prescripción se interrumpirá por cualquier actuación administrativa de la que tenga conocimiento formal el interesado dirigida a la sanción de la infracción". No se exige que sea ejecutable la resolución ni que haya transcurrido el plazo para recurrir; cualquier actuación formal basta.'}},
  {n:53,q:'El plazo de prescripción de las infracciones se reanudará:',o:{a:'Si el procedimiento estuviera paralizado más de un mes por causa no imputable al presunto responsable.',b:'Si el procedimiento estuviera paralizado más de un mes por causa no imputable a la Administración.',c:'Si el procedimiento estuviera paralizado más de un mes por causa no imputable al presunto responsable o a la Administración.',d:'El plazo de prescripción, una vez interrumpido, no se puede reanudar.'},correct:'a',why:{a:'El art. 38.3 LOPSC dispone que, una vez interrumpida la prescripción, "se reanudará el cómputo del plazo de prescripción si el procedimiento estuviera paralizado más de un mes por causa no imputable al presunto responsable". La paralización por causa imputable a la Administración permite la reanudación; la imputable al responsable, no.'}},
  {n:54,q:'¿Cuál es la cuantía de la sanción mínima que se puede imponer por las infracciones reguladas en la LOPSC?',o:{a:'50 euros.',b:'100 euros.',c:'200 euros.',d:'600 euros.'},correct:'b',why:{b:'El art. 39.1 LOPSC dispone que las infracciones leves se sancionarán con multa de 100 a 600 euros. Por tanto, la sanción mínima que se puede imponer es de 100 euros, correspondiente a las infracciones leves.'}},
  {n:55,q:'Para las infracciones muy graves, el grado mínimo comprenderá una multa cuya horquilla oscilará entre:',o:{a:'30.001 a 220.000 euros.',b:'220.001 a 410.000 euros.',c:'410.001 a 510.000 euros.',d:'410.001 a 600.000 euros.'},correct:'a',why:{a:'El art. 39.1.a) LOPSC dispone que para las infracciones muy graves, el grado mínimo comprende la multa de 30.001 a 220.000 euros; el grado medio, de 220.001 a 410.000 euros; y el grado máximo, de 410.001 a 600.000 euros.'}},
  {n:56,q:'¿Qué tipo de sanciones son las que más tiempo tardan en prescribir?',o:{a:'Las sanciones impuestas por infracciones leves.',b:'Las sanciones impuestas por infracciones graves.',c:'Las sanciones impuestas por infracciones muy graves.',d:'Las sanciones impuestas por infracciones graves o muy graves.'},correct:'c',why:{c:'El art. 40.1 LOPSC dispone que las sanciones impuestas por infracciones muy graves prescribirán a los tres años, las impuestas por infracciones graves a los dos años, y las impuestas por infracciones leves al año, computados desde el día siguiente a aquel en que adquiera firmeza en vía administrativa la resolución sancionadora.'}},
  {n:57,q:'En relación con las autoridades competentes para sancionar la LOPSC introdujo como novedad la potestad de sancionar al:',o:{a:'Gobierno de la Nación.',b:'Ministro del Interior.',c:'Secretario de Estado de Seguridad.',d:'Delegado del Gobierno en la Comunidad Autónoma.'},correct:'c',why:{c:'La novedad más significativa que introdujo la LOPSC es que añade al Secretario de Estado de Seguridad como competente para sancionar. Además, la LOPSC sustituyó la referencia a los Gobernadores Civiles por Delegados del Gobierno e incluyó los Subdelegados del Gobierno y Directores Insulares.'}},
  {n:58,q:'¿Cuál de las siguientes no es una autoridad con competencia para sancionar de acuerdo con la LOPSC?',o:{a:'El Ministro del Interior.',b:'Los Subdelegados del Gobierno en las Provincias.',c:'Los Directores Insulares.',d:'Los Directores Generales.'},correct:'d',why:{d:'El art. 5.2 LOPSC enumera como autoridades y órganos competentes: el Ministro del Interior, el Secretario de Estado de Seguridad, los titulares de órganos directivos del Ministerio del Interior con tal condición, los Delegados del Gobierno, los Subdelegados del Gobierno y los Directores Insulares. Los Directores Generales no están incluidos como tales.'}},
  {n:59,q:'Las autoridades y órganos competentes de las Comunidades Autónomas ¿serán competentes para sancionar?',o:{a:'Sí, en cualquier caso.',b:'No, en ningún caso.',c:'Sí, si hubieran asumido competencias para la protección de personas y bienes y para el mantenimiento de la seguridad ciudadana aunque no cuenten con un cuerpo de policía propio.',d:'Sí, si hubieran asumido competencias para la protección de personas y bienes y para el mantenimiento de la seguridad ciudadana y además cuentan con un cuerpo de policía propio.'},correct:'d',why:{d:'El art. 5.3 LOPSC dispone que serán autoridades y órganos competentes "los correspondientes de las comunidades autónomas que hayan asumido competencias para la protección de personas y bienes y para el mantenimiento de la seguridad ciudadana y cuenten con un cuerpo de policía propio". Se requieren ambas condiciones: competencias asumidas Y cuerpo policial propio (caso del País Vasco y Cataluña).'}},
  {n:60,q:'Los Alcaldes ¿podrán imponer sanciones por las infracciones previstas en la LOPSC?',o:{a:'Sí, en cualquier caso.',b:'Sí, cuando se cometieran en espacios públicos municipales o afecten a bienes de titularidad local, siempre que ostenten competencia sobre la materia de acuerdo con la legislación específica.',c:'Sí, cuando se cometieran en espacios públicos municipales o afecten a bienes de titularidad local, siempre que se trate de infracciones leves.',d:'Sí, cuando se cometieran dentro del término municipal.'},correct:'b',why:{b:'El art. 32.3 LOPSC dispone que "los alcaldes podrán imponer las sanciones y adoptar las medidas previstas en esta Ley cuando las infracciones se cometieran en espacios públicos municipales o afecten a bienes de titularidad local, siempre que ostenten competencia sobre la materia de acuerdo con la legislación específica". No se limita a infracciones leves.'}},
  {n:61,q:'La Ley Orgánica 3/2018, de 5 de diciembre, de Protección de Datos Personales y garantía de los derechos digitales (desde ahora LOPDGDD) tiene por objeto adaptar el ordenamiento jurídico español, ¿a qué tipo de norma comunitaria?',o:{a:'Una directiva.',b:'Un reglamento.',c:'Una decisión.',d:'Una recomendación.'},correct:'b',why:{b:'La Ley Orgánica 3/2018 tiene por objeto "adaptar el ordenamiento jurídico español al Reglamento (UE) 2016/679 del Parlamento Europeo y el Consejo, de 27 de abril de 2016, relativo a la protección de las personas físicas en lo que respecta al tratamiento de sus datos personales". Los Reglamentos son obligatorios en todos sus elementos y directamente aplicables en cada Estado miembro.'}},
  {n:62,q:'¿Todo el articulado de la LOPDGDD tiene carácter de ley orgánica?',o:{a:'Sí, pues así se hace constar en sus disposiciones adicionales primera y segunda.',b:'Sí, excepto parte del Título III en el que se regulan los derechos de las personas.',c:'No, ya que a parte del articulado de la misma se le reconoce carácter de ley orgánica, pero otra parte, tal como se establece en su Disposición Adicional Segunda, tiene carácter de ley ordinaria.',d:'No, excepto los principios de protección de datos regulados a lo largo de su Título II.'},correct:'c',why:{c:'La Disposición Final 1.ª LOPDGDD declara que la misma "tiene el carácter de ley orgánica", pero exceptúa de tal condición, atribuyendo "carácter de ley ordinaria" a buena parte de su contenido: el Título IV, el Título VII (salvo arts. 52 y 53), los Títulos VIII y IX, determinados artículos del Título X, las disposiciones adicionales (salvo la 2.ª y 17.ª), las disposiciones transitorias y la mayoría de disposiciones finales.'}},
  {n:63,q:'La nueva LOPDGDD:',o:{a:'Deroga en su totalidad la Ley Orgánica 15/1999 de Protección de Datos de Carácter Personal.',b:'Deroga, con algunas excepciones, la Ley Orgánica 15/1999 de Protección de Datos de Carácter Personal.',c:'Sustituye al Reglamento de la Unión Europea 679/2016, conocido como "Reglamento General de Protección de Datos".',d:'Deroga el Reglamento (UE) 679/2016, conocido como "Reglamento General de Protección de Datos".'},correct:'b',why:{b:'La Ley Orgánica 3/2018 deroga formalmente la Ley Orgánica 15/1999, pero los artículos 23 y 24 de la citada LOPD continúan en vigor en tanto no sean expresamente modificados, sustituidos o derogados. Además, la LOPDGDD ni sustituye ni deroga al Reglamento (UE) 679/2016.'}},
  {n:64,q:'La nueva LOPDGDD no será de aplicación:',o:{a:'A las personas fallecidas.',b:'A los menores de edad y personas dependientes.',c:'A las Administraciones Públicas.',d:'A las personas con discapacidad y personas dependientes.'},correct:'a',why:{a:'El Considerando (27) del RGPD determina que el Reglamento "no se aplica a las personas fallecidas". Igualmente, la LOPDGDD en su art. 2.2.b) dispone que no será de aplicación "a los tratamientos de datos de personas fallecidas, sin perjuicio de lo establecido en el artículo 3", que permite a familiares y herederos solicitar acceso, supresión o rectificación de sus datos.'}},
  {n:65,q:'Los datos personales deberán ser:',o:{a:'Exactos.',b:'Exactos y, si fuera necesario, actualizados.',c:'Exactos, actualizados e identificativos.',d:'Exactos, actualizados, identificativos y de calidad.'},correct:'b',why:{b:'El art. 5.1.d) RGPD y el art. 4 LOPDGDD establecen que los datos personales deben ser exactos y, si fuera necesario, actualizados. Se adoptarán todas las medidas razonables para que se supriman o rectifiquen sin dilación los datos personales que sean inexactos con respecto a los fines para los que se tratan.'}},
  {n:66,q:'¿A quién será imputable la inexactitud de los datos personales?',o:{a:'A la persona titular de los datos.',b:'Al responsable de su tratamiento.',c:'Al mediador o intermediario que hubiese obtenido los datos.',d:'Al encargado del tratamiento de datos.'},correct:'b',why:{b:'La inexactitud de los datos personales es imputable al responsable del tratamiento, que es quien determina los fines y medios del tratamiento. El art. 4.2 LOPDGDD establece los supuestos excepcionales en que dicha inexactitud no le es imputable (datos obtenidos del propio afectado, de un mediador o de un registro público), siempre que haya adoptado medidas razonables.'}},
  {n:67,q:'No será imputable al responsable del tratamiento la inexactitud de los datos personales cuando los datos inexactos hubiesen sido obtenido:',o:{a:'Por el responsable directamente del afectado.',b:'De un registro público por el responsable.',c:'Por el responsable de un mediador o intermediario.',d:'Todas las respuestas son correctas.'},correct:'d',why:{d:'El art. 4.2 LOPDGDD dispone que no será imputable al responsable la inexactitud cuando los datos: a) hubiesen sido obtenidos directamente del afectado; b) hubiesen sido obtenidos de un mediador o intermediario; c) fuesen recibidos de otro responsable en virtud del derecho de portabilidad; d) fuesen obtenidos de un registro público. Todos los supuestos eximen de responsabilidad al responsable del tratamiento.'}},
  {n:68,q:'El deber de confidencialidad de las personas autorizadas para tratar datos personales atañe:',o:{a:'A los responsables del tratamiento de los datos personales.',b:'A los encargados de los datos personales.',c:'A cualquier persona que intervenga en cualquier fase del tratamiento de los datos personales.',d:'Todas las respuestas son correctas.'},correct:'d',why:{d:'El art. 5 LOPDGDD regula la confidencialidad como un deber que atañe a los responsables, encargados y cualquier otra persona que intervenga en cualquier fase del tratamiento. Esta obligación se mantendrá aun cuando hubiese finalizado la relación del obligado con el responsable o encargado del tratamiento.'}},
  {n:69,q:'¿Se admite en la nueva LOPDGDD el consentimiento tácito por parte del interesado para el tratamiento de sus datos personales?',o:{a:'Sí, siempre que se trate de una persona mayor de catorce años.',b:'Sí, siempre que no sea otorgado bajo amenazas o coacciones.',c:'No, ya que la nueva ley exige que se realice mediante una declaración o una clara acción afirmativa.',d:'Sí, siempre que éste sea revocable.'},correct:'c',why:{c:'El art. 6.1 LOPDGDD define el consentimiento como "toda manifestación de voluntad libre, específica, informada e inequívoca por la que este acepta, ya sea mediante una declaración o una clara acción afirmativa, el tratamiento de datos personales". La nueva Ley no permite el consentimiento tácito ni las casillas premarcadas, a diferencia de la antigua LO 15/1999.'}},
  {n:70,q:'El tratamiento de los datos personales de un menor de edad únicamente podrá fundarse en su consentimiento cuando sea:',o:{a:'Mayor de edad.',b:'Mayor de catorce años.',c:'Mayor de dieciséis años.',d:'Mayor de diecisiete años.'},correct:'b',why:{b:'El art. 7.1 LOPDGDD dispone que "el tratamiento de los datos personales de un menor de edad únicamente podrá fundarse en su consentimiento cuando sea mayor de catorce años". España ha ejercido la habilitación del art. 8 RGPD para rebajar la edad mínima de 16 a 14 años. Para menores de 14 años se requiere el consentimiento del titular de la patria potestad o tutela.'}},
  {n:71,q:'La información básica que se debe facilitar al afectado sobre sus datos personales no deberá contener:',o:{a:'La identidad del responsable del tratamiento y de su representante, en su caso.',b:'La finalidad del tratamiento.',c:'La posibilidad de ejercer los derechos de acceso, rectificación, supresión, limitación del tratamiento, supresión, portabilidad y oposición.',d:'El nombre del registro de las actividades de tratamiento.'},correct:'d',why:{d:'El art. 11.2 LOPDGDD dispone que la información básica debe contener al menos: a) la identidad del responsable y su representante, b) la finalidad del tratamiento, c) la posibilidad de ejercer los derechos de los arts. 15 a 22 RGPD. La Ley no establece que deba facilitarse el nombre del registro de las actividades de tratamiento.'}},
  {n:72,q:'El responsable del tratamiento deberá facilitar al interesado la información:',o:{a:'En el plazo de un mes a partir de la recepción de la solicitud, sin que dicho plazo sea prorrogable.',b:'En el plazo de un mes a partir de la recepción de la solicitud, pudiendo prorrogarse dicho plazo otros dos meses en caso necesario, teniendo en cuenta la complejidad y el número de solicitudes.',c:'En el plazo de un mes a partir de la recepción de la solicitud, pudiendo prorrogarse dicho plazo en el caso de que la información sea facilitada por escrito.',d:'En el plazo de un mes a partir de la recepción de la solicitud, pudiendo prorrogarse dicho plazo en el caso de que el interesado solicite la información por medios no electrónicos.'},correct:'b',why:{b:'El art. 12.3 RGPD dispone que el responsable del tratamiento deberá facilitar al interesado la información en el plazo de un mes a partir de la recepción de la solicitud. Dicho plazo podrá prorrogarse otros dos meses en caso necesario, teniendo en cuenta la complejidad y el número de solicitudes.'}},
  {n:73,q:'¿Cuándo se podrá considerar repetitivo el ejercicio del derecho de acceso a los datos personales?',o:{a:'Cuando se acceda en más de una ocasión durante el plazo de seis meses, a menos que exista causa legítima para ello.',b:'Cuando no exista causa legítima para ello.',c:'Cuando se acceda en más de una ocasión durante el plazo de seis meses, aunque no exista causa legítima para ello.',d:'Cuando se acceda en más de una ocasión durante el plazo de seis meses, a menos el acceso se produzca electrónicamente.'},correct:'a',why:{a:'El art. 13.3 LOPDGDD dispone que "se podrá considerar repetitivo el ejercicio del derecho de acceso en más de una ocasión durante el plazo de seis meses, a menos que exista causa legítima para ello". También se considerará excesiva la solicitud cuando el interesado elija un medio que suponga un coste desproporcionado al ofrecido.'}},
  {n:74,q:'El ejercicio del acceso a los datos personales será gratuito:',o:{a:'En cualquier caso.',b:'En cualquier caso, cuando los datos se faciliten por medios electrónicos.',c:'En cualquier caso, sin que se pueda percibir ningún canon basado en los costes administrativos.',d:'Ninguna respuesta es correcta.'},correct:'d',why:{d:'Si bien el RGPD prevé que el ejercicio de los derechos es generalmente gratuito para el interesado, el art. 15 RGPD especifica que el responsable podrá percibir por cualquier copia adicional solicitada un canon razonable basado en los costes administrativos. Ninguna de las opciones a, b y c refleja correctamente esta regla con sus excepciones.'}},
  {n:75,q:'Cuando los datos personales sean inexactos o incompletos el interesado tendrá derecho a ejercer el derecho:',o:{a:'A que se rectifiquen los datos inexactos.',b:'A que se garantice su exactitud.',c:'A que se completen los datos que sean incompletos.',d:'Todas las respuestas son correctas.'},correct:'d',why:{d:'El art. 16 RGPD establece el derecho de rectificación: el interesado tendrá derecho a obtener la rectificación de los datos inexactos que le conciernan, y también "tendrá derecho a que se completen los datos personales que sean incompletos, inclusive mediante una declaración adicional". Ambos aspectos (rectificación e integridad) forman parte del mismo derecho.'}},
  {n:76,q:'El derecho al olvido de los datos personales también se denomina:',o:{a:'Derecho de supresión.',b:'Derecho a la portabilidad.',c:'Derecho de oposición.',d:'Derecho de limitación.'},correct:'a',why:{a:'El derecho al olvido (también denominado derecho de supresión) fue una de las novedades en el RGPD. Supone que el interesado puede pedir la supresión de sus datos personales y, cuando hayan sido publicados en el entorno electrónico, que se informe a otros responsables para que supriman los enlaces, copias o réplicas de los datos.'}},
  {n:77,q:'¿Qué derecho permite al interesado que el responsable del tratamiento de los datos personales tenga que dejar de tratarlos?',o:{a:'El derecho de supresión.',b:'El derecho a la portabilidad.',c:'El derecho de oposición.',d:'El derecho de limitación.'},correct:'c',why:{c:'El derecho de oposición permite al interesado oponerse en cualquier momento al tratamiento de sus datos personales, de manera que el responsable del tratamiento dejará de tratar los datos, salvo que acredite motivos legítimos imperiosos que prevalezcan sobre los intereses, derechos y libertades del interesado, o para la formulación, ejercicio o defensa de reclamaciones.'}},
  {n:78,q:'¿Qué derecho permite al interesado que el responsable del tratamiento de los datos personales aplique medidas para evitar su modificación o, en su caso, su borrado o supresión?',o:{a:'El derecho de supresión.',b:'El derecho a la portabilidad.',c:'El derecho de oposición.',d:'El derecho a la limitación.'},correct:'d',why:{d:'El derecho a la limitación del tratamiento permite al interesado solicitar al responsable que aplique medidas sobre sus datos para evitar, entre otras cosas, su modificación o borrado. Se denominaba anteriormente "derecho al bloqueo". El art. 18.1 RGPD regula los supuestos en que procede: impugnación de exactitud, tratamiento ilícito, necesidad para reclamaciones, u oposición en curso.'}},
  {n:79,q:'La elaboración de perfiles consiste en:',o:{a:'Utilizar los datos personales de una persona física para analizar o predecir aspectos relativos a su rendimiento profesional, situación económica, salud, preferencias personales, intereses, fiabilidad, comportamiento, ubicación o movimientos.',b:'El tratamiento de datos personales de manera tal que ya no puedan atribuirse a un interesado.',c:'El marcado de los datos de carácter personal conservados con el fin de limitar su tratamiento en el futuro.',d:'Cualquier operación o conjunto de operaciones realizadas sobre datos personales o conjuntos de datos personales, ya sea por procedimientos automatizados o por otros procedimientos.'},correct:'a',why:{a:'El art. 4.4 RGPD define la elaboración de perfiles como "toda forma de tratamiento automatizado de datos personales consistente en utilizar datos personales para evaluar determinados aspectos personales de una persona física, en particular para analizar o predecir aspectos relativos al rendimiento profesional, situación económica, salud, preferencias personales, intereses, fiabilidad, comportamiento, ubicación o movimientos".'}},
  {n:80,q:'¿Cuál de las siguientes proposiciones respecto del responsable del tratamiento de datos personales no es correcta?',o:{a:'Puede ser una persona física o una persona jurídica.',b:'Puede ser una Administración Pública.',c:'Es quien debe asumir la responsabilidad del cumplimiento de las normas sobre protección de datos y de qué manera los interesados pueden ejercer sus derechos.',d:'Sus funciones se limitan al tratamiento de los datos personales.'},correct:'d',why:{d:'El art. 4.7 RGPD define al responsable del tratamiento como quien "determine los fines y medios del tratamiento". Sus funciones no se limitan al tratamiento: determina los fines y medios, asume la responsabilidad del cumplimiento de las normas y decide cómo los interesados ejercen sus derechos. Es el encargado quien se limita a tratar los datos por cuenta del responsable.'}},
  {n:81,q:'¿Cuál de las siguientes proposiciones respecto del encargado del tratamiento de datos personales no es correcta?',o:{a:'Trata los datos por cuenta del responsable de tratamiento.',b:'Sigue las instrucciones del responsable del tratamiento.',c:'Decide sobre el tratamiento de los datos personales.',d:'Es una entidad jurídica independiente del responsable de tratamiento.'},correct:'c',why:{c:'El art. 4.8 RGPD define al encargado del tratamiento como quien "trate datos personales por cuenta del responsable del tratamiento". El encargado sigue las instrucciones del responsable y no decide sobre los fines y medios del tratamiento. Lo relevante es que el encargado, a diferencia del responsable, no decide sobre el tratamiento de los datos personales.'}},
  {n:82,q:'¿Cuál de las siguientes proposiciones respecto del Delegado de Protección de datos personales no es correcta?',o:{a:'Su figura se define en el RGPD.',b:'Supervisa el cumplimiento de la normativa de protección de datos en su organización.',c:'Debe tener un conocimiento especializado, tanto en materia de protección de datos personales como de los tratamientos que lleve a cabo la organización que le designe.',d:'Informará y asesorará sobre sus obligaciones en materia de protección de datos al responsable o al encargado del tratamiento.'},correct:'a',why:{a:'El RGPD no ofrece una definición precisa de la figura del Delegado de Protección de Datos. Tomando elementos del Considerando 97 RGPD, se puede definir como una persona con conocimientos técnicos especializados del Derecho y de la práctica de protección de datos que asesora y supervisa el cumplimiento en la organización. El RGPD regula su figura (arts. 37-39) pero no la define formalmente.'}},
  {n:83,q:'La Agencia Española de Protección de Datos es una autoridad administrativa independiente:',o:{a:'De ámbito estatal.',b:'Con personalidad jurídica y plena capacidad pública y privada.',c:'Que actúa con plena independencia de los poderes públicos en el ejercicio de sus funciones.',d:'Todas las respuestas son correctas.'},correct:'d',why:{d:'El art. 44.1 LOPDGDD establece que la Agencia Española de Protección de Datos "es una autoridad administrativa independiente de ámbito estatal, de las previstas en la Ley 40/2015, con personalidad jurídica y plena capacidad pública y privada, que actúa con plena independencia de los poderes públicos en el ejercicio de sus funciones". Las tres proposiciones son correctas.'}},
  {n:84,q:'Real Decreto 428/1993, de 26 de marzo regula:',o:{a:'El Estatuto de la Agencia de Protección de Datos.',b:'El Estatuto del Delegado de Protección de Datos.',c:'Las obligaciones del Responsable del tratamiento de los datos.',d:'El tratamiento de los datos personales con fines de videovigilancia.'},correct:'a',why:{a:'El Real Decreto 428/1993, de 26 de marzo, aprueba el Estatuto de la Agencia de Protección de Datos y desarrolla en la actualidad el Capítulo I del Título VII de la LOPDGDD. Parte de su articulado ha quedado anticuado como consecuencia de la publicación de la propia LOPDGDD y las recientes leyes de procedimiento administrativo.'}},
  {n:85,q:'La denominación oficial de la Agencia Española de Protección de Datos, de conformidad con lo establecido en el artículo 109.3 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, será:',o:{a:'Agencia Española de Protección de Datos, Autoridad Responsable Dependiente.',b:'Agencia Española de Protección de Datos, Autoridad Administrativa Independiente.',c:'Agencia Española de Protección de Datos, Autoridad Administrativa Dependiente.',d:'Agencia Española de Protección de Datos, Autoridad Responsable Independiente.'},correct:'b',why:{b:'El art. 44.1 LOPDGDD dispone que "su denominación oficial, de conformidad con lo establecido en el artículo 109.3 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, será «Agencia Española de Protección de Datos, Autoridad Administrativa Independiente»".'}},
  {n:86,q:'La Agencia Española de Protección de Datos se relaciona con el Gobierno a través de:',o:{a:'El Ministerio de Justicia.',b:'El Consejo de Ministros.',c:'El Consejo General del Poder Judicial.',d:'El Ministerio del Interior.'},correct:'a',why:{a:'El art. 44.1 LOPDGDD en su tercer inciso dispone que la Agencia Española de Protección de Datos "se relaciona con el Gobierno a través del Ministerio de Justicia". La Presidencia de la Agencia y su Adjunto serán nombrados por el Gobierno, a propuesta del Ministerio de Justicia.'}},
  {n:87,q:'¿Cuál de las siguientes proposiciones sobre la Presidencia y el Adjunto de la Agencia Española de Protección de Datos no es correcta?',o:{a:'Serán nombrados por el Consejo de Ministros mediante Real Decreto.',b:'Su mandato tiene una duración de cinco años.',c:'Su mandato no puede ser renovado.',d:'La presidencia de la Agencia Española de Protección de datos no podrá delegar en su adjunto las funciones relacionadas con los procedimientos en caso de posible vulneración de la normativa de protección de datos.'},correct:'c',why:{c:'El art. 48.5 LOPDGDD dispone que "el mandato de la Presidencia y del Adjunto de la Agencia Española de Protección de Datos tiene una duración de cinco años y puede ser renovado para otro período de igual duración". Por tanto, el mandato sí puede ser renovado, lo que hace incorrecta la afirmación de la opción c).'}},
  {n:88,q:'¿Quién asesora a la Presidencia de la Agencia Española de Protección de Datos?',o:{a:'Un Adjunto.',b:'Un Consejo Consultivo.',c:'Un gabinete jurídico.',d:'Un Vocal en el que podrá delegar sus funciones.'},correct:'b',why:{b:'El art. 49 LOPDGDD dispone que la presidencia de la Agencia de Protección de Datos estará asesorada por un Consejo Consultivo cuyas decisiones no tendrán en ningún caso carácter vinculante. Para ser miembro del Consejo Consultivo se requieren conocimientos especializados en el Derecho y la práctica en materia de protección de datos.'}},
  {n:89,q:'La legislación reguladora del ejercicio del alto cargo de la Administración General del Estado será aplicable:',o:{a:'A todos los miembros del Consejo Consultivo.',b:'A la Presidencia.',c:'Al Adjunto.',d:'A la Presidencia y al Adjunto.'},correct:'d',why:{d:'El art. 48.2 LOPDGDD dispone que la Presidencia y el Adjunto "ejercerán sus funciones con plena independencia y objetividad y no estarán sujetos a instrucción alguna en su desempeño. Les será aplicable la legislación reguladora del ejercicio del alto cargo de la Administración General del Estado". No se aplica a todos los miembros del Consejo Consultivo.'}},
  {n:90,q:'La Presidencia y el Adjunto de la Agencia Española de Protección de Datos serán nombrados por el Consejo de Ministros mediante:',o:{a:'Real Decreto.',b:'Ley ordinaria.',c:'Ley orgánica.',d:'Orden ministerial.'},correct:'a',why:{a:'El art. 48.4 LOPDGDD dispone que la Presidencia y el Adjunto de la Agencia Española de Protección de Datos serán nombrados "por el Consejo de Ministros mediante Real Decreto". El nombramiento se propone por el Ministerio de Justicia (art. 48.3 LOPDGDD).'}}
];
